package com.gameaggregator.contractservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="contracts") public class Contract{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String contractNumber;@Column(nullable=false)public String status="DRAFT";@Column(nullable=false)public UUID createdBy;@Column(nullable=false)public Instant createdAt=Instant.now();public Instant terminatedAt;public String terminationReason;@Version public long revision;protected Contract(){}public Contract(String n,UUID u){contractNumber=n;createdBy=u;}}